<script>
 import { automatorSession, automatorAvailability, automatorTypes } from './automator-state.js';
 import { automatorLibrary } from './automator-engine.js';
 import { automatorMenuItems } from './automator-menus.js';
 import './automator.css';
 let {state: automatorState,profile,windowId,files,applications,available=true,active=true,execute,registerView}=$props();
 let root,scroller,error=$state(''),newType=$state('workflow'),saveName=$state('Untitled'),variableName=$state('Files'),variableValue=$state('');
 let session=$derived(automatorSession(automatorState,windowId)),capability=$derived(automatorAvailability(profile)),busy=$derived(session?.status==='running');
 let filesBound=$derived(Array.isArray(files)),applicationsBound=$derived(Array.isArray(applications)),sourcesBound=$derived(filesBound&&applicationsBound);
 let folders=$derived(filesBound?files.filter(f=>f.kind==='folder'&&!f.deleted):[]),inputs=$derived(filesBound?files.filter(f=>!f.deleted&&f.kind!=='application'):[]);
 let library=$derived(automatorLibrary.filter(a=>(session?.category==='All'||a.category===session?.category)&&`${a.name} ${a.description}`.toLowerCase().includes(session?.search.toLowerCase()??'')));
 const names={'workflow':'Workflow','application':'Application','quick-action':'Quick Action','print-plugin':'Print Plugin','folder-action':'Folder Action','calendar-alarm':'Calendar Alarm','image-capture-plugin':'Image Capture Plugin','dictation-command':'Dictation Command'};
 const typeName=type=>type==='quick-action'&&profile.id.includes('high-sierra')?'Service':names[type];
 async function send(command,payload={}) {if(typeof execute!=='function'){error='Registered Root command executor unavailable.';return {status:'rejected',error:{code:'unavailable',message:error}};}const r=await execute(command,{windowId},payload);error=r?.status==='applied'?'':r?.error?.message??'Root did not acknowledge the command.';return r;}
 function update(action,key,value){return send('automator.editAction',{action:{...action,params:{...action.params,[key]:value}}});}
 function toggleFile(action,id){const ids=action.params.fileIds;return update(action,'fileIds',ids.includes(id)?ids.filter(i=>i!==id):[...ids,id]);}
 function drop(event,action){event.preventDefault();event.stopPropagation();if(busy)return;try{const kind=event.dataTransfer.getData('application/x-jesteros-automator-action');if(!action&&kind){send('automator.addAction',{kind});return;}if(!filesBound){error='Actual Root Files metadata is unavailable.';return;}const many=event.dataTransfer.getData('application/x-jesteros-file-ids'),one=event.dataTransfer.getData('application/x-jesteros-file-id'),ids=many?JSON.parse(many):one?[one]:[];if(!Array.isArray(ids)||ids.some(id=>typeof id!=='string'))return;if(action)update(action,'fileIds',[...new Set([...action.params.fileIds,...ids])]);else send('automator.addFiles',{fileIds:ids});}catch{error='Drop actual Files items only.';}}
 $effect(()=>{if(!root||typeof registerView!=='function'||!session)return;const node=root,originalState=automatorState,originalSession=session,scrollNode=scroller,id=windowId;const mounted=()=>node===root&&node.isConnected&&automatorState===originalState&&automatorSession(automatorState,id)===originalSession&&available===true&&sourcesBound&&typeof execute==='function';const facade={available:mounted,focus(controlId,guard){if(guard?.()!==true||!mounted())return false;const control=Array.from(node.querySelectorAll('[data-control]')).find(c=>c.dataset.control===controlId);if(!control||control.disabled)return false;control.focus();return guard()===true&&mounted()&&document.activeElement===control;},scroll({top},guard){if(guard?.()!==true||!mounted()||scrollNode!==scroller)return false;scrollNode.scrollTop=top;return guard()===true&&mounted();}};return registerView(id,facade);});
</script>
{#if session}
<section bind:this={root} class="automator-app" class:classic={/high-sierra|mojave/u.test(profile.id)} class:windows={profile.id.startsWith('windows11')} class:qualified={capability.qualified} class:active aria-label={capability.label}>
 <nav class="auto-menus" aria-label="Automator menus">{#each automatorMenuItems(automatorState,windowId) as menu}<details><summary>{menu.label}</summary><div class="auto-menu">{#each menu.items as item}<button disabled={!item.enabled} onclick={()=>send(item.command,item.payload)}>{item.label}</button>{/each}</div></details>{/each}</nav>
 <header class="auto-toolbar"><button data-control="library" disabled={busy} onclick={()=>send('automator.preferences',{values:{...automatorState.preferences,showLibrary:!automatorState.preferences.showLibrary}})}>▤<span>Library</span></button><button data-control="open" disabled={busy||!filesBound} onclick={()=>send('automator.open')}>↗<span>Open</span></button><button data-control="save" disabled={busy||!filesBound} onclick={()=>send('automator.save')}>▣<span>Save</span></button><div class="auto-title"><strong>{session.title}{session.dirty?' — Edited':''}</strong><span>{typeName(session.type)}</span></div><button data-control="stop" disabled={!busy} onclick={()=>send('automator.stop')}>■<span>Stop</span></button><button data-control="run" disabled={busy||!sourcesBound||!session.actions.length} onclick={()=>send('automator.run')}>▶<span>Run</span></button></header>
 {#if !sourcesBound}<div role="alert" class="auto-source-unavailable">Actual Root {filesBound?'registered application inventory':applicationsBound?'Files metadata':'Files metadata and registered application inventory'} unavailable. Source controls and the native execution facade are unavailable; no substitute sources are created.</div>{/if}
 <div class="auto-body" class:without-library={!automatorState.preferences.showLibrary}>
 {#if automatorState.preferences.showLibrary}<aside class="auto-library"><div class="auto-library-tabs"><strong>Actions</strong><button disabled={busy} onclick={()=>send('automator.preferences',{values:{...automatorState.preferences,showVariables:!automatorState.preferences.showVariables}})}>Variables</button></div><input data-control="search" type="search" placeholder="Search Actions" value={session.search} disabled={busy} oninput={e=>send('automator.search',{query:e.currentTarget.value})}/><div class="auto-library-columns"><div class="auto-categories">{#each ['All','Files & Folders','Photos','Text','Utilities'] as category}<button class:selected={session.category===category} disabled={busy} onclick={()=>send('automator.search',{query:session.search,category})}>{category==='All'?'▾ Library':category}</button>{/each}</div><div class="auto-action-list">{#each library as entry}<button disabled={busy} draggable={!busy} ondragstart={e=>e.dataTransfer.setData('application/x-jesteros-automator-action',entry.kind)} title={entry.description} onclick={()=>send('automator.addAction',{kind:entry.kind})}><span>{entry.category==='Photos'?'▧':entry.category==='Text'?'▤':'⚙'}</span>{entry.name}</button>{/each}{#if !library.length}<p>No matching actions</p>{/if}</div></div><div class="auto-description"><strong>{automatorLibrary.find(a=>a.kind===session.actions.find(a=>a.id===session.selected)?.kind)?.name??'Build a workflow'}</strong><p>{automatorLibrary.find(a=>a.kind===session.actions.find(a=>a.id===session.selected)?.kind)?.description??'Click an action to add it. Actions run from top to bottom against local Files and registered applications.'}</p></div></aside>{/if}
 <main class="auto-main"><div class="auto-input-strip"><strong>{typeName(session.type)}</strong><span>{session.type==='workflow'?'Receives Files from Get Specified Finder Items or explicit Run input.':'Local document type; run here with explicit Files input. No host OS trigger is installed.'}</span><button disabled={busy} onclick={()=>send('automator.panel',{panel:'new'})}>New…</button></div><div bind:this={scroller} class="auto-workflow" role="group" ondragover={e=>e.preventDefault()} ondrop={e=>drop(e)} aria-label="Workflow actions">
 {#if !session.actions.length}<div class="auto-empty"><span>⚙</span><h2>Drag actions or files here to build your workflow</h2><p>Choose an action in the Library. Every action below performs a real bounded local operation.</p><button onclick={()=>send('automator.addAction',{kind:'get-files'})}>Get Specified Finder Items</button></div>{/if}
 {#each session.actions as action,index (action.id)}{@const entry=automatorLibrary.find(a=>a.kind===action.kind)}<article class="auto-action" class:selected={session.selected===action.id} class:disabled={!action.enabled}>
 <header><button class="auto-action-name" disabled={busy} onclick={()=>send('automator.selectAction',{actionId:action.id})}>{index+1}. {entry.name}</button><label title="Enable action"><input type="checkbox" checked={action.enabled} disabled={busy} onchange={e=>send('automator.editAction',{action:{...action,enabled:e.currentTarget.checked}})}/></label><button aria-label="Move action up" disabled={busy||index===0} onclick={()=>send('automator.moveAction',{actionId:action.id,index:index-1})}>↑</button><button aria-label="Move action down" disabled={busy||index===session.actions.length-1} onclick={()=>send('automator.moveAction',{actionId:action.id,index:index+1})}>↓</button><button aria-label="Delete action" disabled={busy} onclick={()=>send('automator.deleteAction',{actionId:action.id})}>×</button></header>
 <div class="auto-params">
 {#if action.kind==='get-files'}<div class="auto-files" role="group" aria-label="Specified Files" ondragover={e=>e.preventDefault()} ondrop={e=>drop(e,action)}>{#each action.params.fileIds as id}<div><span>{filesBound?files.find(f=>f.id===id)?.name??'Unavailable File: '+id:'Root Files metadata unavailable: '+id}</span><button disabled={busy} aria-label="Remove File" onclick={()=>toggleFile(action,id)}>−</button></div>{/each}<select data-control={'files-'+action.id} value="" disabled={busy||!filesBound} onchange={e=>{if(e.currentTarget.value)toggleFile(action,e.currentTarget.value);e.currentTarget.value='';}}><option value="">{filesBound?'Add actual Files item…':'Root Files metadata unavailable'}</option>{#each inputs.filter(f=>!action.params.fileIds.includes(f.id)) as file}<option value={file.id}>{file.name} ({file.kind})</option>{/each}</select><small>Drop actual Files items here; IDs and original revisions are guarded.</small></div>
 {:else if action.kind==='rename-files'}<label>Make names<select disabled={busy} value={action.params.mode} onchange={e=>update(action,'mode',e.currentTarget.value)}><option value="prefix">Add Text</option><option value="replace">Replace Text</option><option value="sequence">Make Sequential</option></select></label>{#if action.params.mode==='replace'}<label>Find<input disabled={busy} value={action.params.find} maxlength="128" onchange={e=>update(action,'find',e.currentTarget.value)}/></label>{/if}<label>{action.params.mode==='sequence'?'New name':'Text'}<input disabled={busy} value={action.params.text} maxlength="128" onchange={e=>update(action,'text',e.currentTarget.value)}/></label>{#if action.params.mode==='sequence'}<label>Start numbers at<input type="number" min="1" max="999999" disabled={busy} value={action.params.start} onchange={e=>update(action,'start',Number(e.currentTarget.value))}/></label>{/if}
 {:else if ['copy-files','scale-images','convert-documents'].includes(action.kind)}<label>To<select disabled={busy||!filesBound} value={action.params.parentId} onchange={e=>update(action,'parentId',e.currentTarget.value)}>{#if !filesBound}<option value={action.params.parentId}>Root Files destinations unavailable</option>{/if}{#each folders as folder}<option value={folder.id}>{folder.name}</option>{/each}</select></label><label>Filename suffix<input disabled={busy} maxlength="64" value={action.params.suffix} onchange={e=>update(action,'suffix',e.currentTarget.value)}/></label>{#if action.kind==='scale-images'}<label>To Size (pixels)<input type="number" min="1" max="4096" disabled={busy} value={action.params.width} onchange={e=>update(action,'width',Number(e.currentTarget.value))}/></label><label>Rotate<select disabled={busy} value={action.params.rotation} onchange={e=>update(action,'rotation',Number(e.currentTarget.value))}>{#each [0,90,180,270] as angle}<option value={angle}>{angle}° clockwise</option>{/each}</select></label><label>Format<select disabled={busy} value={action.params.format} onchange={e=>update(action,'format',e.currentTarget.value)}>{#each ['png','jpeg','webp'] as format}<option value={format}>{format.toUpperCase()}</option>{/each}</select></label>{:else if action.kind==='convert-documents'}<label>Format<select disabled={busy} value={action.params.format} onchange={e=>update(action,'format',e.currentTarget.value)}><option value="rtf">Rich Text Format (.rtf)</option><option value="txt">Plain Text (.txt)</option></select></label><label>Append text<textarea disabled={busy} maxlength="4096" value={action.params.append} onchange={e=>update(action,'append',e.currentTarget.value)}></textarea></label>{/if}
 {:else if action.kind==='set-variable'||action.kind==='get-variable'}<label>Variable<select disabled={busy} value={action.params.name} onchange={e=>update(action,'name',e.currentTarget.value)}><option value={action.params.name}>{action.params.name}</option>{#each session.variables.filter(v=>v.name!==action.params.name) as variable}<option value={variable.name}>{variable.name}</option>{/each}</select></label><small>Declare variables below. Set stores current file references; Get restores them during this run.</small>
 {:else if action.kind==='open-app'||action.kind==='quit-app'}<label>Application<select disabled={busy||!applicationsBound} value={action.params.appId} onchange={e=>update(action,'appId',e.currentTarget.value)}>{#if applicationsBound}{#each applications as app}<option value={app.appId??app.id}>{app.name??app.label??app.title??app.appId??app.id}</option>{/each}{:else}<option value={action.params.appId}>Registered Root applications unavailable</option>{/if}</select></label><small>Executes the registered Root application command, with native document close decisions.</small>
 {:else}<p>Passes current Files input to the workflow Results panel.</p>{/if}
 </div><footer><span>{action.enabled?'Action enabled':'Action disabled'}</span>{#if session.log.some(l=>l.actionId===action.id&&l.level==='info')}<strong>✓ Completed</strong>{/if}</footer></article>{/each}
 </div>
 {#if automatorState.preferences.showVariables}<section class="auto-variables"><h3>Variables <small>Use ${'{Name}'} in text parameters</small></h3>{#each session.variables as variable}<div><input aria-label="Variable name" disabled={busy} value={variable.name} maxlength="64" onchange={e=>send('automator.setVariable',{variable:{...variable,name:e.currentTarget.value}})}/><input aria-label="Variable value" disabled={busy} value={variable.value} maxlength="4096" onchange={e=>send('automator.setVariable',{variable:{...variable,value:e.currentTarget.value}})}/><button aria-label="Delete variable" disabled={busy} onclick={()=>send('automator.deleteVariable',{variableId:variable.id})}>−</button></div>{/each}<div><input placeholder="Variable name" bind:value={variableName} maxlength="64" disabled={busy}/><input placeholder="Text value" bind:value={variableValue} maxlength="4096" disabled={busy}/><button disabled={busy} onclick={()=>send('automator.setVariable',{variable:{id:'auto-variable-'+automatorState.nextId,name:variableName,value:variableValue}})}>+</button></div></section>{/if}
 {#if automatorState.preferences.showLog}<section class="auto-output"><header><strong>Log</strong><span>{session.status}</span><button disabled={busy} onclick={()=>send('automator.clearLog')}>Clear</button></header><ol>{#each session.log as row}<li class:error={row.level==='error'}><time>{new Date(row.time).toISOString().slice(11,19)}</time><span>{row.message}</span></li>{/each}</ol><h3>Results</h3><ul>{#each session.results as row}<li><strong>{row.name}</strong><span>{row.mime||row.summary}</span><code>{row.fileId}</code></li>{/each}</ul></section>{/if}
 </main></div>
 <footer class="auto-status"><span>{session.actions.length} action{session.actions.length===1?'':'s'}</span><span>{session.status==='running'?'Running — Stop discards pending Files effects':session.status}</span><span>{capability.disclosure}</span></footer>
 {#if error}<div class="auto-error" role="alert">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
 {#if session.panel!=='none'}<div class="auto-shade"><section class="auto-sheet" role="dialog" aria-modal="true" aria-label={'Automator '+session.panel}>
 {#if session.panel==='new'}<h2>Choose a type for your document:</h2><div class="auto-types">{#each automatorTypes as type}<button class:selected={newType===type} onclick={()=>newType=type}><span>{type==='application'?'⚙':type==='calendar-alarm'?'▦':'▤'}</span>{typeName(type)}</button>{/each}</div><p>All types are legitimate local .jworkflow documents, executed here with explicit input. Host watchers, services, alarms, print and dictation hooks are not installed.</p><div class="auto-sheet-buttons"><button onclick={()=>send('automator.panel',{panel:'none'})}>Cancel</button><button onclick={()=>send('automator.new',{type:newType})}>Choose</button></div>
 {:else if session.panel==='save'}<h2>Save Workflow As</h2><label>Save As<input bind:value={saveName} maxlength="240"/></label><p>Local JSON workflow (.jworkflow), not an Apple workflow bundle. Saves to actual Documents.</p><div class="auto-sheet-buttons"><button onclick={()=>send('automator.panel',{panel:'none'})}>Cancel</button><button onclick={()=>send('automator.save',{name:saveName,saveAs:true})}>Save</button></div>
 {:else if session.panel==='preferences'}<h2>Automator {(/sonoma|golden-gate/u.test(profile.id))?'Settings':'Preferences'}</h2>{#each [['showLibrary','Show Library'],['showVariables','Show Variables'],['showLog','Show Log'],['confirmRun','Confirm before running workflows']] as [key,label]}<label><input type="checkbox" checked={automatorState.preferences[key]} onchange={e=>send('automator.preferences',{values:{...automatorState.preferences,[key]:e.currentTarget.checked}})}/>{label}</label>{/each}<button onclick={()=>send('automator.panel',{panel:'none'})}>Done</button>
 {:else if session.panel==='close'}<h2>Save changes to {session.title}?</h2><div class="auto-sheet-buttons"><button onclick={()=>send('automator.closeDecision',{decision:'discard'})}>Don’t Save</button><button onclick={()=>send('automator.closeDecision',{decision:'cancel'})}>Cancel</button><button onclick={()=>send('automator.closeDecision',{decision:'save'})}>Save</button></div>
 {:else if session.panel==='run-confirm'}<h2>Run this workflow?</h2><p>File changes publish together only after all Files actions succeed. Registered application commands obey their own native close decisions.</p><div class="auto-sheet-buttons"><button onclick={()=>send('automator.panel',{panel:'none'})}>Cancel</button><button onclick={()=>send('automator.run',{confirmed:true})}>Run</button></div>
 {:else}<h2>Automator Help</h2><p>Add actions from the Library, edit parameters and reorder them with arrows. Get Specified Finder Items provides original File input. Copy preserves real contents, Rename changes actual metadata, image actions decode and encode raster pixels, and document actions use the shared plain-text/RTF codecs.</p><p>Variables have text values usable as ${'{Name}'}. Set/Get Value of Variable preserves actual file references during a run. A failed Files workflow makes no partial changes. Stop discards pending effects. Results contain actual destination File IDs.</p><p>{capability.disclosure}</p><button onclick={()=>send('automator.panel',{panel:'none'})}>Done</button>{/if}
 </section></div>{/if}
</section>
{/if}
